qs_goal_teach() {
  case "$1" in
    'brief')
      q_say 'Five jobs before launch. Read them all first.'
      ;;
    'alarm')
      q_say 'ps lists the programs running in this terminal; each has a PID, a process id. kill PID asks that program to stop.'
      ;;
    'rename')
      q_say 'A for loop runs the same commands for each item: for f in telemetry/*.tmp; do mv "$f" "${f%.tmp}.log"; done. Each time round, $f is one file; ${f%.tmp} is its name with .tmp cut off. Quotes keep names with spaces in one piece.'
      ;;
    'sensors')
      q_say 'A script is commands in a file. Open the editor with nano check.sh and write: a loop over sensors/*.txt; for each, temp=$(cut -d= -f2 "$f") puts the number after = into a variable; if [ "$temp" -gt 90 ]; then basename "$f" .txt; fi prints the name of a hot one. Save, chmod +x check.sh, then ./check.sh | ./uplink.'
      ;;
    'beacon')
      q_say 'Inside a script, $1 is the first word typed after its name, $2 the second, and so on. A beacon.sh that says echo "BEACON $1" prints whatever callsign it is given. Then ./beacon.sh KESTREL | ./transmitter.'
      ;;
    'launch')
      q_say 'Everything on the checklist is done. Run the launch.'
      ;;
  esac
}

