qs_goal_solution() {
  case "$1" in
    'brief')
      printf '%s\n' 'cat briefing.txt'
      ;;
    'alarm')
      printf '%s\n' 'ps'
      printf '%s\n' 'kill 4100'
      ;;
    'rename')
      printf '%s\n' 'for f in telemetry/*.tmp; do mv "$f" "${f%.tmp}.log"; done'
      ;;
    'sensors')
      printf '%s\n' 'cat > check.sh << '\''EOF'\''
      #!/usr/bin/env bash
      # Prints every sensor hotter than 90.
      for f in sensors/*.txt; do
        temp=$(cut -d= -f2 "$f")
        if [ "$temp" -gt 90 ]; then
          basename "$f" .txt
        fi
      done
      EOF'
      printf '%s\n' 'chmod +x check.sh'
      printf '%s\n' './check.sh | ./uplink'
      ;;
    'beacon')
      printf '%s\n' 'echo '\''echo "BEACON $1"'\'' > beacon.sh'
      printf '%s\n' 'chmod +x beacon.sh'
      printf '%s\n' './beacon.sh KESTREL | ./transmitter'
      ;;
    'launch')
      printf '%s\n' './launch'
      ;;
  esac
}

qs_finish_when() {
